/// <summary>
///     The <c>AVACustFreeInvoiceFrm_Extension</c> class is the extension for <c>CustFreeInvoice</c>
/// </summary>
[ExtensionOf(FormStr(CustFreeInvoice))]
final class AVACustFreeInvoiceFrm_Extension
{
    public UserId                   frmUserId;
    public HcmWorkerRecId           frmHcmWorkerRecId;
    public HCMWorker                frmHCMWorker;

    public Args                     frmArgs;
    public boolean                  frmBonusMode;
    public CustInvoiceTable         frmCustInvoiceTable;

}

Method.Source:
/// <summary>
///    AVA <c>init</c> method.
/// </summary>
public void init()
{
    this.avaInitFrmValues();

    next init();

    this.avaInitQueryRanges();

    this.avaSetFormControls();
}

/// <summary>
///    AVA <c>avaInitFrmValues</c> method.
/// </summary>
void avaInitFrmValues()
{
    Common              locCommon;

    frmHCMWorker        = HCMWorker::find(HcmWorkerLookup::currentWorker());

    frmUserId           = curUserId();
    frmHcmWorkerRecId   = HcmWorkerLookup::currentWorker();
    frmHCMWorker        = HCMWorker::find(frmHcmWorkerRecId);

    if(this.args())
    {
        frmArgs = new Args();
        frmArgs = this.args();
    }

    if(     this.args()
        &&  this.args().menuItemName() == menuitemDisplayStr(AVABonusCustInvoiceDisplay))
    {
        frmBonusMode = true;

        if(frmArgs.record())
        {
            locCommon = frmArgs.record();

            switch(locCommon.TableId)
            {
                case Tablenum(CustInvoiceTable):
                    frmCustInvoiceTable  = locCommon;
                    break;
            }
        }
    }
}

/// <summary>
///    AVA <c>avaSetFormControls</c> method.
/// </summary>
void avaSetFormControls()
{
    // List
    FormGroupControl    locFGC_ListPage_BonusDates;
    FormGroupControl    locFGC_ListPage_BonusInvoice;

    // Header Fast Tab
    FormGroupControl    locFGC_HeaderFastTab_BonusFields;
    FormControl         locFGC_HeaderFastTab_BonusFields_AVABonusAlliance;
    FormControl         locFGC_HeaderFastTab_BonusFields_AVABonusCustAccount;

    // Positions Header
    FormTabPageControl  locFGC_PosHeaderFastTab_Bonus;
    FormGroupControl    locFGC_PosHeaderFastTab_BonusInvoice;
    FormGroupControl    locFGC_PosHeaderFastTab_BonusDates;
    FormGroupControl    locFGC_PosHeaderFastTab_BonusFields;
    FormStringControl   locFGC_PosHeaderFastTab_BonusFields_AVABonusAlliance;
    FormControl         locFC_PosHeaderFastTab_BonusFields_AVABonusAlliance;
    FormControl         locFC_PosHeaderFastTab_BonusFields_AVABonusCustAccount;

    // Positions
    FormGridControl     locFGridCAVACustInvoiceLineAdjust;
    FormGroupControl    locFGC_PositionsGrid_Bonus;
    FormControl         locFC_CVInvoiceDetailsTabPage_Bonus;
    FormControl         locFC_CVInvoiceDetailsTapBage_Adjustments;
    /* alternative
    FormTabPageControl  locFTPC_CVInvoiceDetailsTabPage_Bonus;
    FormTabPageControl  locFTPC_CVInvoiceDetailsTapBage_Adjustments;
    */

    FormControl         locFC_CVInvoiceDetailsTabPageGroup_BonusDates;

    // data sources
    FormDataSource      locAVACustInvoiceLineAdjustDS;

    FormStringControl   locCVInvoiceDetailsTabPageGroup_BonusFields_AVABonusAlliance;


    // List
    locFGC_ListPage_BonusDates      = FormGroupOverviewGrid_BonusDates;
    locFGC_ListPage_BonusInvoice    = FormGroupOverviewGrid_BonusInvoice;

    // Header Fast Tab
    locFGC_HeaderFastTab_BonusFields                    = FastTabGroup_BonusFields;
    locFGC_HeaderFastTab_BonusFields_AVABonusAlliance   = this.design().controlName(formControlStr(CustFreeInvoice, FormGroupCVHeaderFastTab_BonusFields_AVABonusAlliance));
    locFGC_HeaderFastTab_BonusFields_AVABonusCustAccount =  this.design().controlName(formControlStr(CustFreeInvoice, FormGroupCVHeaderFastTab_BonusFields_AVABonusCustAccount));

    // Positions Header
    locFGC_PosHeaderFastTab_Bonus                           = FastTab_Bonus;
    locFGC_PosHeaderFastTab_BonusInvoice                    = FormGroupCVHeaderFastTab_BonusInvoice;
    locFGC_PosHeaderFastTab_BonusDates                      = FormGroupCVHeaderFastTab_BonusDates;
    locFGC_PosHeaderFastTab_BonusFields                     = FormGroupCVHeaderFastTab_BonusFields;
    locFGC_PosHeaderFastTab_BonusFields_AVABonusAlliance    = FastTabGroup_BonusFields_AVABonusAlliance; // use locFC_PosHeaderFastTab_BonusFields_AVABonusAlliance because of field group assignment causing extra settings like autodecleration on fields will be lost
    locFC_PosHeaderFastTab_BonusFields_AVABonusAlliance     = this.design().controlName(formControlStr(CustFreeInvoice, FastTabGroup_BonusFields_AVABonusAlliance));
    locFC_PosHeaderFastTab_BonusFields_AVABonusCustAccount  = this.design().controlName(formControlStr(CustFreeInvoice, FastTabGroup_BonusFields_AVABonusCustAccount));
    // Positions
    locFGridCAVACustInvoiceLineAdjust           = this.design().controlName(formControlStr(CustFreeInvoice, AVACustInvoiceLineAdjust));
    locFGC_PositionsGrid_Bonus                  = LinesGridGroup_Bonus;
    locFC_CVInvoiceDetailsTabPage_Bonus         = this.design().controlName(formControlStr(CustFreeInvoice, CVInvoiceDetailsTabPage_Bonus));
    locFC_CVInvoiceDetailsTapBage_Adjustments   = this.design().controlName(formControlStr(CustFreeInvoice, CVInvoiceDetailsTapBage_Adjustments));
    /* alternative
    locFTPC_CVInvoiceDetailsTabPage_Bonus       = CVInvoiceDetailsTabPage_Bonus;
    locFTPC_CVInvoiceDetailsTapBage_Adjustments = CVInvoiceDetailsTapBage_Adjustments;
    */

    locFC_CVInvoiceDetailsTabPageGroup_BonusDates = this.design().controlName(formControlStr(CustFreeInvoice, CVInvoiceDetailsTabPageGroup_BonusDates));

    // Positions Fast Tab
    FormTabPageControl locCVLineDetailsFastTab = CVLineDetailsFastTab;

    // data sources
    locAVACustInvoiceLineAdjustDS = AVACustInvoiceLineAdjust_DS;

    locCVInvoiceDetailsTabPageGroup_BonusFields_AVABonusAlliance = CVInvoiceDetailsTabPageGroup_BonusFields_AVABonusAlliance;


    if(frmBonusMode)
    {
        locFGridCAVACustInvoiceLineAdjust           = this.design().controlName(formControlStr(CustFreeInvoice, AVACustInvoiceLineAdjust));
        /*
        locFormControl = this.design().controlName(formControlStr(CustFreeInvoice, FormGroupOverviewGrid_Bonus));
        locFormControl.visible(false);
        */
        locFGC_ListPage_BonusDates.visible(true);
        locFGC_ListPage_BonusInvoice.visible(false);

        locFGC_PosHeaderFastTab_Bonus.visible(true);
        locFGC_PosHeaderFastTab_BonusInvoice.visible(true);
        locFGC_PosHeaderFastTab_BonusDates.visible(true);
        locFGC_PosHeaderFastTab_BonusFields.visible(true);

        locFGC_PositionsGrid_Bonus.visible(true);
        locFC_CVInvoiceDetailsTabPage_Bonus.visible(true);
        /* alternative
        locFTPC_CVInvoiceDetailsTabPage_Bonus.visible(true);
        */

        locCVLineDetailsFastTab.enabled(true);

        locFC_CVInvoiceDetailsTapBage_Adjustments.visible(true);
        locFC_CVInvoiceDetailsTapBage_Adjustments.enabled(true);
        locFC_CVInvoiceDetailsTapBage_Adjustments.allowEdit(true);
        /* alternative
        locFTPC_CVInvoiceDetailsTapBage_Adjustments.visible(true);
        locFTPC_CVInvoiceDetailsTapBage_Adjustments.enabled(true);
        locFTPC_CVInvoiceDetailsTapBage_Adjustments.allowEdit(true);
        */
        locFGridCAVACustInvoiceLineAdjust.enabled(true);
        locFGridCAVACustInvoiceLineAdjust.allowEdit(true);

        locAVACustInvoiceLineAdjustDS.allowEdit(true);

        locCVInvoiceDetailsTabPageGroup_BonusFields_AVABonusAlliance.allowEdit(true);
    }

    if(frmCustInvoiceTable.RecId)
    {
        if(frmCustInvoiceTable.Posted)
        {
            /* even if Posted fast Tab should be editable task 11487
            locFGC_PosHeaderFastTab_Bonus.allowEdit(false);
            locFGC_PosHeaderFastTab_BonusInvoice.allowEdit(false);

            locFGC_PositionsGrid_Bonus.allowEdit(false);
            locFTPC_CVInvoiceDetailsTabPage_Bonus.allowEdit(false);
            */
            locFGC_PosHeaderFastTab_Bonus.allowEdit(true);
            //locFGC_PosHeaderFastTab_BonusInvoice.allowEdit(false);

            locFGC_PositionsGrid_Bonus.allowEdit(true);

            locFC_CVInvoiceDetailsTabPage_Bonus.allowEdit(true);
            /* alternative
            locFTPC_CVInvoiceDetailsTabPage_Bonus.allowEdit(true);
            */

            locFC_CVInvoiceDetailsTabPageGroup_BonusDates.allowEdit(true);
        }
        else
        {
            locFGC_PosHeaderFastTab_Bonus.allowEdit(true);
            locFGC_PosHeaderFastTab_BonusInvoice.allowEdit(true);

            locFGC_PositionsGrid_Bonus.allowEdit(true);

            locFC_CVInvoiceDetailsTabPage_Bonus.allowEdit(true);
            /* alternative
            locFTPC_CVInvoiceDetailsTabPage_Bonus.allowEdit(true);
            */

            locFC_CVInvoiceDetailsTabPageGroup_BonusDates.allowEdit(true);
        }


        if(frmCustInvoiceTable.AVABonusInvoice == NoYes::Yes)
        {
            locFGC_HeaderFastTab_BonusFields.allowEdit(true);
            locFGC_PosHeaderFastTab_BonusFields.allowEdit(true);

            if(frmCustInvoiceTable.AVABonusAllocationBase  == AVABonusAllocationBase::Alliance)
            {
                locFGC_HeaderFastTab_BonusFields_AVABonusAlliance.allowEdit(true);
                //locFGC_PosHeaderFastTab_BonusFields_AVABonusAlliance.allowEdit(true);
                locFC_PosHeaderFastTab_BonusFields_AVABonusAlliance.allowEdit(true);
                locFGC_HeaderFastTab_BonusFields_AVABonusAlliance.allowEdit(false);
                locFC_PosHeaderFastTab_BonusFields_AVABonusCustAccount.allowEdit(false);
            }
            else
            {
                locFGC_HeaderFastTab_BonusFields_AVABonusAlliance.allowEdit(false);
                //locFGC_PosHeaderFastTab_BonusFields_AVABonusAlliance.allowEdit(false);
                locFC_PosHeaderFastTab_BonusFields_AVABonusAlliance.allowEdit(false);
                locFGC_HeaderFastTab_BonusFields_AVABonusAlliance.allowEdit(true);
                locFC_PosHeaderFastTab_BonusFields_AVABonusCustAccount.allowEdit(true);
            }
        }
        else
        {
            locFGC_HeaderFastTab_BonusFields_AVABonusAlliance.allowEdit(false);
            //locFGC_PosHeaderFastTab_BonusFields_AVABonusAlliance.allowEdit(false);
            locFC_PosHeaderFastTab_BonusFields_AVABonusAlliance.allowEdit(false);
            locFGC_HeaderFastTab_BonusFields_AVABonusAlliance.allowEdit(false);
            locFC_PosHeaderFastTab_BonusFields_AVABonusCustAccount.allowEdit(false);
        }
    }

}

/// <summary>
///     AVA <c>avaInitQueryRanges</c> method.
/// </summary>
public void avaInitQueryRanges()
{
    this.avaSetQueryRangeCustInvoiceTable();
    this.avaSetQueryRangeCustInvoiceLine();
}

/// <summary>
///     AVA <c>avaSetQueryRangeCustInvoiceTable</c> method.
/// </summary>
public void avaSetQueryRangeCustInvoiceTable()
{
    AVABonusInvoice         qValue;
    FormDataSource          locCustInvoiceTableDS;
    QueryBuildDataSource    locQBDS;

    locCustInvoiceTableDS   = custInvoiceTable_DS;
    locQBDS                 = locCustInvoiceTableDS.queryBuildDataSource();

    if(frmBonusMode)
    {
        qValue  = NoYes::Yes;
    }

    if (qValue == NoYes::Yes)
    {
        SysQuery::findOrCreateRange(locQBDS, fieldNum(CustInvoiceTable, AVABonusInvoice)).value(queryValue(qValue));
    }
    else
    {
        SysQuery::findOrCreateRange(locQBDS, fieldNum(CustInvoiceTable, AVABonusInvoice)).value(SysQueryRangeUtil::valueUnlimited());
    }
}

/// <summary>
