public void avaSetQueryRangeCustInvoiceLine()
{
    //InventSiteId    qValue;
    FormDataSource  locCustInvoiceLineDS;

    locCustInvoiceLineDS    = custInvoiceLine_DS;
    /*
    qValue                  = '';

    if (qValue != '')
    {
        SysQuery::findOrCreateRange(locCustInvoiceLineDS.queryBuildDataSource(), fieldNum(CustInvoiceLine, AVABonusInvoice)).value(queryValue(qValue));
    }
    else
    {
        SysQuery::findOrCreateRange(locCustInvoiceLineDS.queryBuildDataSource(), fieldNum(CustInvoiceLine, AVABonusInvoice)).value(SysQueryRangeUtil::valueUnlimited());
    }
    */
}

/// <summary>
///     AVA <c>allowedit</c> method.
///     AVA - Schneider 07.05.2024
/// </summary>
void allowedit()
{
    next allowedit();

    FormTabPageControl     cvLines = this.design().controlName('cvLineDetailsFastTab');
    cvLines.enabled(true);


    this.avaSetFormControls();



}

public void setFieldsEditable()
{
    next   setFieldsEditable();
    FormTabPageControl     cvLines = this.design().controlName('cvLineDetailsFastTab');
    cvLines.enabled(true);
}
